import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Las Reglas de Travesía Transplanar","description":"","frontmatter":{},"headers":[],"relativePath":"es/81-位面穿梭规则.md","filePath":"es/81-位面穿梭规则.md"}'),r={name:"es/81-位面穿梭规则.md"};function t(l,e,s,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="las-reglas-de-travesia-transplanar" tabindex="-1">Las Reglas de Travesía Transplanar <a class="header-anchor" href="#las-reglas-de-travesia-transplanar" aria-label="Permalink to &quot;Las Reglas de Travesía Transplanar&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>81</td></tr><tr><td>Módulo</td><td>Interacción Transplanar y Reglas Temporales</td></tr><tr><td>Palabras clave</td><td>travesía transplanar, permisos de travesía, umbrales de energía, calibración del Ancla, prevención y control de la contaminación</td></tr></tbody></table><h2 id="i-el-posicionamiento-juridico-de-la-travesia" tabindex="-1">I. El Posicionamiento Jurídico de la Travesía <a class="header-anchor" href="#i-el-posicionamiento-juridico-de-la-travesia" aria-label="Permalink to &quot;I. El Posicionamiento Jurídico de la Travesía&quot;">​</a></h2><p>La travesía transplanar designa el comportamiento por el cual un individuo o un grupo de seres vivos cruza una barrera de leyes para pasar de un plano a otro mediante medios técnicos o capacidades de cultivo. Dentro del marco jurídico de la Civilización Simbiótica del Ancla, la travesía transplanar pertenece a la categoría de &quot;comportamiento especial de alto riesgo&quot; y debe estar sujeta a una estricta gestión de permisos y supervisión del proceso. El artículo 47 de la Constitución Simbiótica estipula claramente: &quot;Ninguna organización ni individuo podrá realizar travesías transplanares sin autorización, ni utilizar la travesía transplanar para actividades de depredación, interferencia o contaminación contra la civilización de otros planos.&quot;</p><p>La razón fundamental por la que la travesía transplanar requiere un control estricto es que el propio comportamiento de travesía puede causar múltiples impactos en el plano objetivo: perturbación de leyes, inyección de energía, contaminación de la conciencia, invasión microbiana e interferencia cultural. Estos impactos pueden, en el caso más leve, desencadenar anomalías locales en el plano objetivo, y en el peor, alterar su trayectoria de evolución civilizacional, o incluso provocar el colapso de sus leyes. Por lo tanto, el objetivo central de las reglas de travesía es &quot;mantener el impacto externo del comportamiento de travesía dentro de un umbral aceptable&quot;.</p><h2 id="ii-el-sistema-jerarquico-de-permisos-de-travesia" tabindex="-1">II. El Sistema Jerárquico de Permisos de Travesía <a class="header-anchor" href="#ii-el-sistema-jerarquico-de-permisos-de-travesia" aria-label="Permalink to &quot;II. El Sistema Jerárquico de Permisos de Travesía&quot;">​</a></h2><p>El Universo Hengyuan implementa un sistema jerárquico de permisos de travesía transplanar, dividiendo los permisos en cuatro niveles según el propósito de la travesía, el tipo de plano objetivo y las cualificaciones del viajero:</p><table tabindex="0"><thead><tr><th>Nivel de permiso</th><th>Escenario aplicable</th><th>Órgano de aprobación</th><th>Validez</th><th>Condiciones adicionales</th></tr></thead><tbody><tr><td>Nivel A (Observación arqueológica)</td><td>Arqueología puramente observacional, sin ningún contacto físico</td><td>Administración de Planos</td><td>Misión única</td><td>Debe adoptar el esquema de Espejo de Réplica + espacio aislado</td></tr><tr><td>Nivel B (Intercambio académico)</td><td>Intercambio limitado de conocimientos con la civilización del plano objetivo</td><td>Administración de Planos + Ministerio de Cultura</td><td>Máximo un año</td><td>Debe firmarse un acuerdo de no interferencia mutua</td></tr><tr><td>Nivel C (Colaboración de recursos)</td><td>Colaboración de recursos y tecnología sobre la base de la igualdad y el beneficio mutuo</td><td>Aprobación especial de la Asamblea Legislativa del Ancla</td><td>Máximo tres años</td><td>Debe obtenerse el consentimiento de la civilización del plano objetivo</td></tr><tr><td>Nivel D (Intervención de emergencia)</td><td>Intervención humanitaria cuando el plano objetivo enfrenta una crisis de nivel de extinción</td><td>Resolución de emergencia de la Asamblea Legislativa del Ancla</td><td>Duración de la crisis</td><td>Debe presentarse posteriormente un informe completo de intervención</td></tr></tbody></table><p>Los permisos de travesía de cualquier nivel prohíben los siguientes comportamientos: saquear la energía de origen del plano objetivo, imponer por la fuerza la ideología del propio plano, realizar modificaciones genéticas o de conciencia sin consentimiento, establecer bases militares permanentes en el plano objetivo, y cualquier forma de dominación colonial.</p><h2 id="iii-requisitos-tecnicos-y-umbrales-de-energia-de-la-travesia" tabindex="-1">III. Requisitos Técnicos y Umbrales de Energía de la Travesía <a class="header-anchor" href="#iii-requisitos-tecnicos-y-umbrales-de-energia-de-la-travesia" aria-label="Permalink to &quot;III. Requisitos Técnicos y Umbrales de Energía de la Travesía&quot;">​</a></h2><p>La travesía transplanar debe satisfacer estrictas condiciones técnicas. Primero, el viajero debe poseer un cultivo superior al tercer nivel (la Etapa Huàkōng) del &quot;sistema de despacho de principios legales espaciales&quot;, o viajar en un vehículo de travesía transplanar que cumpla los estándares. Segundo, tanto el punto de partida como el de llegada deben contar con un Ancla para la calibración de coordenadas; la travesía a ciegas sin posicionamiento del Ancla está estrictamente prohibida.</p><p>El consumo de energía del proceso de travesía es proporcional a la fuerza de la barrera de leyes del plano objetivo. El Universo Hengyuan ha establecido una &quot;tabla estandarizada de umbrales de energía de travesía&quot;. La energía mínima requerida para la travesía hacia diferentes tipos de planos es la siguiente:</p><ul><li>Plano de Dominio Material: 1.000 unidades de energía estándar</li><li>Plano de Energía Manifestada: 5.000 unidades de energía estándar</li><li>Plano de Dominio de la Conciencia: 20.000 unidades de energía estándar</li><li>Plano de Leyes Fragmentadas: 50.000 unidades de energía estándar (con una tasa de éxito inferior al 30 %)</li><li>Plano Cercano al Origen: valor teórico superior a 100.000; sin registro exitoso hasta la fecha</li></ul><p>La energía de travesía debe ser transportada por el propio viajero o vehículo; está prohibido extraer energía del plano objetivo para el proceso de travesía. Esta disposición tiene como objetivo impedir que la travesía cause una depredación de energía sobre el plano objetivo.</p><h2 id="iv-prevencion-y-control-de-la-contaminacion-en-el-proceso-de-travesia" tabindex="-1">IV. Prevención y Control de la Contaminación en el Proceso de Travesía <a class="header-anchor" href="#iv-prevencion-y-control-de-la-contaminacion-en-el-proceso-de-travesia" aria-label="Permalink to &quot;IV. Prevención y Control de la Contaminación en el Proceso de Travesía&quot;">​</a></h2><p>Uno de los mayores riesgos de la travesía transplanar es la &quot;contaminación transplanar&quot;, que incluye la contaminación biológica (llevar microorganismos del propio plano al plano objetivo), la contaminación energética (la interferencia de los residuos de energía del propio plano con las leyes del plano objetivo) y la contaminación de la conciencia (la influencia de las fluctuaciones de conciencia del viajero sobre el dominio de conciencia del plano objetivo).</p><p>Para prevenir y controlar la contaminación, todos los viajeros deben completar el &quot;procedimiento de purificación en tres niveles&quot; antes de partir:</p><ol><li><strong>Purificación biológica</strong>: realizar 72 horas de cribado y eliminación de microorganismos en un espacio aislado, garantizando que no se transporten patógenos del propio plano.</li><li><strong>Purificación energética</strong>: ajustar la frecuencia energética del viajero a un rango compatible con el plano objetivo mediante el dispositivo de calibración del Ancla, reduciendo las reacciones de repulsión energética.</li><li><strong>Purificación de la conciencia</strong>: someterse a un entrenamiento de blindaje de la conciencia para garantizar que no se emitan activamente fluctuaciones de pensamiento que puedan interferir con el dominio de conciencia del plano objetivo durante la travesía.</li></ol><p>Además, el ámbito de actividad del viajero en el plano objetivo está estrictamente limitado a la &quot;zona delimitada por el permiso de travesía&quot;, prohibiéndose la dispersión no autorizada. Tras regresar al propio plano, el viajero debe someterse nuevamente a una observación en cuarentena, por un período no inferior a 30 días convertidos según la velocidad temporal del plano objetivo.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Las reglas de travesía transplanar son la primera línea de defensa de seguridad de la interacción transplanar. A través del triple mecanismo de clasificación de permisos, umbrales técnicos y prevención y control de la contaminación, garantizan que la travesía se desarrolle siempre en el carril de &quot;bajo impacto, trazabilidad y rendición de cuentas&quot;. El propósito último de las reglas no es restringir el intercambio entre civilizaciones, sino hacer que el intercambio ocurra de manera simbiótica, y no de manera depredadora.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>80-位面理论与分类 (La Teoría de los Planos y la Clasificación)</li><li>88-跨位面伦理准则 (Las Normas Éticas Transplanares)</li><li>62-空间法理技术实现 (La Implementación Tecnológica de los Principios Legales Espaciales)</li></ul>',23)])])}const v=a(r,[["render",t]]);export{m as __pageData,v as default};
